/**
 * A KOJI BED, PAINTED FOR THE KOJI ROOM, AT EVERY STAGE.
 *
 * The workshop's cedar tray is a three-quarter painting, and in the koji room's
 * straight-on perspective it floated and tilted. These were painted for the room:
 * a level tray seen from the front (the floor and the backs of the boards) and the
 * same tray turned so its long side runs back along a side wall — mirrored for
 * the right-hand wall, the rule the tools on the workshop shelves taught.
 *
 * Four stages, so a bed reads at a glance: laid (steamed grain), bloom (the first
 * white), peak (a full white felt) and spore (going yellow-green). Keyed off
 * magenta; 56 kB for all eight.
 */
export type BedView = 'front' | 'turn';
export type BedStage = 'laid' | 'bloom' | 'peak' | 'spore';

export const KOJI_BED: Record<BedView, Record<BedStage, { w: number; h: number; src: string }>> = {
  front: {
    laid: { w: 240, h: 92, src: 'data:image/webp;base64,' },
    bloom: { w: 240, h: 92, src: 'data:image/webp;base64,' },
    peak: { w: 240, h: 94, src: 'data:image/webp;base64,' },
    spore: { w: 240, h: 94, src: 'data:image/webp;base64,' },
  },
  turn: {
    laid: { w: 240, h: 123, src: 'data:image/webp;base64,' },
    bloom: { w: 240, h: 121, src: 'data:image/webp;base64,' },
    peak: { w: 240, h: 122, src: 'data:image/webp;base64,' },
    spore: { w: 240, h: 122, src: 'data:image/webp;base64,' },
  },
};
